from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal, TypeAlias

from ..contracts.types import ChatMessage
from ..utils.core import JsonValue, MetadataDict

EnvironmentMetadata = MetadataDict
RewardReturnType = Literal["binary", "numeric"]


@dataclass(frozen=True)
class EnvironmentTurn:
    """One observable message or event in an environment episode."""

    role: str
    content: str
    name: str | None = None
    metadata: EnvironmentMetadata = field(default_factory=dict)

    def to_message(self) -> ChatMessage:
        return {"role": self.role, "content": self.content}

    def to_dict(self) -> dict[str, JsonValue]:
        payload: dict[str, JsonValue] = {
            "role": self.role,
            "content": self.content,
        }
        if self.name:
            payload["name"] = self.name
        if self.metadata:
            payload["metadata"] = self.metadata
        return payload


@dataclass(slots=True)
class EnvironmentGeneration:
    """Model output returned by an environment callback used during local eval."""

    response_text: str
    latency_ms: int | None = None
    total_tokens: int | None = None
    metadata: EnvironmentMetadata = field(default_factory=dict)


GenerationValue: TypeAlias = str | EnvironmentGeneration


@dataclass(frozen=True)
class EnvironmentStepResult:
    """Environment response after one assistant action in an episode."""

    done: bool = True
    messages: tuple[ChatMessage, ...] = ()
    final_response_text: str | None = None
    metadata: EnvironmentMetadata = field(default_factory=dict)


@dataclass(frozen=True)
class EnvironmentEpisode:
    """Completed trajectory used by evals and environment-driven workflows.

    A single-turn episode usually has one assistant response. A multi-turn
    episode includes the full observable transcript as ``turns``.
    """

    messages: tuple[ChatMessage, ...]
    response_text: str
    turns: tuple[EnvironmentTurn, ...] = ()
    metadata: EnvironmentMetadata = field(default_factory=dict)
    latency_ms: int | None = None
    total_tokens: int | None = None

    def to_dict(self) -> dict[str, JsonValue]:
        payload: dict[str, JsonValue] = {
            "response_text": self.response_text,
            "messages": [
                {"role": message["role"], "content": message["content"]}
                for message in self.messages
            ],
        }
        if self.turns:
            payload["turns"] = [turn.to_dict() for turn in self.turns]
        if self.metadata:
            payload["metadata"] = self.metadata
        if self.latency_ms is not None:
            payload["latency_ms"] = self.latency_ms
        if self.total_tokens is not None:
            payload["total_tokens"] = self.total_tokens
        return payload


@dataclass(frozen=True)
class RewardMetric:
    """A named component that explains how a reward score was produced.

    This shape is intentionally JSON-compatible because it is stored inside
    eval_tasks.scorers_data[*].metrics.
    """

    name: str
    score: float | None = None
    value: JsonValue | None = None
    success: bool | None = None
    threshold: float | None = None
    weight: float | None = None
    reason: str | None = None
    metadata: EnvironmentMetadata = field(default_factory=dict)


@dataclass(frozen=True)
class RewardResult:
    score: float
    metadata: EnvironmentMetadata = field(default_factory=dict)
    name: str = "environment_reward"
    success: bool | None = None
    threshold: float | None = None
    value: JsonValue | None = None
    reason: str | None = None
    error: str | None = None
    return_type: RewardReturnType = "numeric"
    metrics: tuple[RewardMetric, ...] = ()
    latency_ms: int | None = None
    total_tokens: int | None = None

    def resolved_success(self) -> bool:
        if self.success is not None:
            return self.success
        if self.error:
            return False
        if self.threshold is not None:
            return self.score >= self.threshold
        return self.score > 0.0

    def resolved_value(self) -> JsonValue:
        if self.value is not None:
            return self.value
        if self.return_type == "binary":
            return self.resolved_success()
        return self.score


__all__ = [
    "EnvironmentEpisode",
    "EnvironmentGeneration",
    "EnvironmentStepResult",
    "EnvironmentTurn",
    "GenerationValue",
    "RewardMetric",
    "RewardResult",
]
